sys_script_client.script:
function onChange(control, oldValue, newValue, isLoading, isTemplate) {
    if (isLoading || newValue === '') {
        g_form.hideFieldMsg("max_capacity", true);

        if (!isLoading && g_form.isNewRecord()) {
            g_form.clearValue("avaible_vacancies");
        }
        return;
    }
    var cleanedValue = newValue.replace(',', '.');
    var maxCapacity = parseFloat(cleanedValue);

    if (isNaN(maxCapacity) || maxCapacity <= 0 || !Number.isInteger(maxCapacity)) {
        g_form.clearValue("max_capacity");

        if (g_form.isNewRecord()) {
            g_form.clearValue("avaible_vacancies");
        }

        g_form.showFieldMsg("max_capacity", "Please enter a valid positive integer.", "error");
        return;
    }

    if (g_form.isNewRecord()) {

        g_form.hideFieldMsg("max_capacity", true);
        g_form.setValue("avaible_vacancies", maxCapacity.toString());

    } else {
        g_form.hideFieldMsg("max_capacity", true);
    }
}
